function(container, apiUrl, tables) {
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[0];
  const categoryTable = tables.find(t => t.tableName === '商品カテゴリマスタ') || tables[1];
  const stockTable = tables.find(t => t.tableName === '在庫マスタ') || tables[4];

  let allProducts = [];
  let compareList = [];

  // カテゴリマップを作成
  const categoryMap = {};
  if (categoryTable && categoryTable.records) {
    categoryTable.records.forEach(cat => {
      categoryMap[cat.id] = cat.カテゴリ名 || cat.categoryName || 'その他';
    });
  }

  // 在庫情報マップを作成
  const stockMap = {};
  if (stockTable && stockTable.records) {
    stockTable.records.forEach(stock => {
      stockMap[stock.商品ID || stock.productId] = {
        currentStock: stock.現在在庫数 || stock.currentStock || 0,
        status: stock.在庫状態 || stock.stockStatus || '在庫あり'
      };
    });
  }

  // 商品一覧を描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const resultCount = container.querySelector('#result-count');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: var(--text-muted);">該当する商品がありません</td></tr>';
      resultCount.textContent = '0件';
      return;
    }

    resultCount.textContent = `${products.length}件`;

    tbody.innerHTML = products.map(product => {
      const categoryName = categoryMap[product.カテゴリID || product.categoryId] || 'その他';
      const stock = stockMap[product.id] || { currentStock: 0, status: '在庫切れ' };
      const isComparing = compareList.some(p => p.id === product.id);

      return `
        <tr data-id="${product.id}">
          <td style="text-align: center;">
            <input type="checkbox" class="compare-checkbox" data-product-id="${product.id}" 
                   ${isComparing ? 'checked' : ''} 
                   style="accent-color: var(--primary);">
          </td>
          <td style="text-align: center;">
            <div style="width: 60px; height: 45px; background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 12px; color: var(--text-muted);">
              画像
            </div>
          </td>
          <td>
            <div style="font-weight: 500; color: var(--text); margin-bottom: 2px;">${product.商品名 || product.productName || ''}</div>
            <div style="font-size: 12px; color: var(--text-muted);">${product.商品コード || product.productCode || ''}</div>
          </td>
          <td style="color: var(--text);">${categoryName}</td>
          <td style="text-align: right; color: var(--text);">¥${(product.単価 || product.unitPrice || 0).toLocaleString()}</td>
          <td style="text-align: right; color: var(--text);">${stock.currentStock}</td>
          <td>
            <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; 
                         background: ${stock.status === '在庫あり' ? 'rgba(34, 197, 94, 0.1)' : 
                                    stock.status === '在庫僅少' ? 'rgba(251, 191, 36, 0.1)' : 'rgba(239, 68, 68, 0.1)'};
                         color: ${stock.status === '在庫あり' ? '#22c55e' : 
                                 stock.status === '在庫僅少' ? '#fbbf24' : '#ef4444'};">
              ${stock.status}
            </span>
          </td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${product.id}" 
                    style="padding: 4px 8px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 比較リストを描画
  function renderCompareList() {
    const compareContainer = container.querySelector('#compare-list');
    const compareEmpty = container.querySelector('#compare-empty');
    const compareBtn = container.querySelector('#btn-compare');

    if (compareList.length === 0) {
      compareEmpty.style.display = 'block';
      compareBtn.disabled = true;
      return;
    }

    compareEmpty.style.display = 'none';
    compareBtn.disabled = false;

    const compareHtml = compareList.map(product => {
      const categoryName = categoryMap[product.カテゴリID || product.categoryId] || 'その他';
      const stock = stockMap[product.id] || { currentStock: 0, status: '在庫切れ' };

      return `
        <div style="border: 1px solid var(--border); border-radius: 6px; padding: 12px; margin-bottom: 8px; background: var(--bg-main);">
          <div style="display: flex; justify-content: space-between; align-items: start;">
            <div style="flex: 1;">
              <div style="font-weight: 500; font-size: 14px; color: var(--text); margin-bottom: 4px;">${product.商品名 || product.productName || ''}</div>
              <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px;">${categoryName}</div>
              <div style="font-size: 14px; color: var(--text);">¥${(product.単価 || product.unitPrice || 0).toLocaleString()}</div>
            </div>
            <button class="remove-compare" data-product-id="${product.id}" 
                    style="background: none; border: none; color: var(--text-muted); cursor: pointer; padding: 4px;">×</button>
          </div>
        </div>
      `;
    }).join('');

    compareContainer.innerHTML = compareHtml + '<div id="compare-empty" style="display: none;"></div>';
  }

  // 比較詳細モーダルを表示
  function showCompareModal() {
    if (compareList.length < 2) {
      alert('比較するには2つ以上の商品を選択してください');
      return;
    }

    const modal = container.querySelector('#compare-modal');
    const headers = container.querySelector('#compare-headers');
    const tbody = container.querySelector('#compare-detail-tbody');

    // ヘッダー作成
    headers.innerHTML = compareList.map(product => 
      `<th style="min-width: 150px;">${product.商品名 || product.productName || ''}</th>`
    ).join('');

    // 比較項目作成
    const compareItems = [
      { label: '商品コード', key: 'productCode' },
      { label: 'カテゴリ', key: 'category' },
      { label: '単価', key: 'unitPrice' },
      { label: '単位', key: 'unit' },
      { label: '在庫数', key: 'stock' },
      { label: '在庫状況', key: 'stockStatus' },
      { label: '最小発注数', key: 'minOrder' },
      { label: '商品説明', key: 'description' }
    ];

    tbody.innerHTML = compareItems.map(item => {
      const cells = compareList.map(product => {
        let value = '';
        switch(item.key) {
          case 'productCode':
            value = product.商品コード || product.productCode || '';
            break;
          case 'category':
            value = categoryMap[product.カテゴリID || product.categoryId] || 'その他';
            break;
          case 'unitPrice':
            value = '¥' + (product.単価 || product.unitPrice || 0).toLocaleString();
            break;
          case 'unit':
            value = product.単位 || product.unit || '';
            break;
          case 'stock':
            const stock = stockMap[product.id] || { currentStock: 0 };
            value = stock.currentStock.toString();
            break;
          case 'stockStatus':
            const stockStatus = stockMap[product.id] || { status: '在庫切れ' };
            value = stockStatus.status;
            break;
          case 'minOrder':
            value = (product.最小発注数 || product.minOrderQty || 1).toString();
            break;
          case 'description':
            value = product.商品説明 || product.description || '';
            break;
        }
        return `<td style="color: var(--text);">${value}</td>`;
      }).join('');

      return `<tr><td style="font-weight: 500; color: var(--text); background: var(--bg-main);">${item.label}</td>${cells}</tr>`;
    }).join('');

    modal.style.display = 'block';
  }

  // 検索実行
  function performSearch() {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const priceMin = parseInt(container.querySelector('#price-min').value) || 0;
    const priceMax = parseInt(container.querySelector('#price-max').value) || Infinity;
    const stockFilter = container.querySelector('#stock-filter').value;

    let filtered = allProducts.filter(product => {
      // キーワード検索
      if (keyword) {
        const productName = (product.商品名 || product.productName || '').toLowerCase();
        const productCode = (product.商品コード || product.productCode || '').toLowerCase();
        if (!productName.includes(keyword) && !productCode.includes(keyword)) {
          return false;
        }
      }

      // カテゴリフィルター
      if (category) {
        const productCategory = categoryMap[product.カテゴリID || product.categoryId] || 'その他';
        if (productCategory !== category) {
          return false;
        }
      }

      // 価格フィルター
      const price = product.単価 || product.unitPrice || 0;
      if (price < priceMin || price > priceMax) {
        return false;
      }

      // 在庫フィルター
      if (stockFilter) {
        const stock = stockMap[product.id] || { status: '在庫切れ' };
        if (stock.status !== stockFilter) {
          return false;
        }
      }

      return true;
    });

    renderProducts(filtered);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const products = await window.aivicApi.list(0);
      if (products) {
        allProducts = products;
        renderProducts(allProducts);
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
      allProducts = productTable.records || [];
      renderProducts(allProducts);
    }
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  // 比較チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('compare-checkbox')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);

      if (e.target.checked) {
        if (compareList.length >= 5) {
          alert('比較できる商品は最大5つまでです');
          e.target.checked = false;
          return;
        }
        if (product && !compareList.some(p => p.id === productId)) {
          compareList.push(product);
        }
      } else {
        compareList = compareList.filter(p => p.id !== productId);
      }

      renderCompareList();
    }
  });

  // 比較リストから削除
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-compare')) {
      const productId = e.target.dataset.productId;
      compareList = compareList.filter(p => p.id !== productId);

      // チェックボックスも外す
      const checkbox = container.querySelector(`input[data-product-id="${productId}"]`);
      if (checkbox) checkbox.checked = false;

      renderCompareList();
    }
  });

  // 比較クリア
  container.querySelector('#btn-clear-compare').addEventListener('click', () => {
    compareList = [];
    container.querySelectorAll('.compare-checkbox').forEach(cb => cb.checked = false);
    renderCompareList();
  });

  // 比較表示
  container.querySelector('#btn-compare').addEventListener('click', showCompareModal);

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#compare-modal').style.display = 'none';
  });

  // 発注画面へ
  container.querySelector('#btn-order-selected').addEventListener('click', () => {
    if (compareList.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }
    // 選択商品のIDを発注画面に渡す
    const productIds = compareList.map(p => p.id).join(',');
    window.showScreen('scr-1780291074387', { selectedProducts: productIds });
  });

  // 商品詳細
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-btn')) {
      const productId = e.target.dataset.id;
      // 商品詳細画面があれば遷移
      console.log('商品詳細:', productId);
    }
  });

  // Enter キーで検索
  container.addEventListener('keypress', (e) => {
    if (e.key === 'Enter' && e.target.matches('#search-keyword, #price-min, #price-max')) {
      performSearch();
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let selectedProducts = new Map(); // 商品ID -> {product, quantity, subtotal}

  // 顧客情報を設定（ログインユーザーから取得）
  function setCustomerInfo() {
    const loginUsers = tables.find(t => t.tableName === 'ログインユーザー')?.records || [];
    const customers = tables.find(t => t.tableName === '顧客マスタ')?.records || [];

    if (loginUsers.length > 0 && customers.length > 0) {
      const currentUser = loginUsers[0];
      const customer = customers.find(c => c.顧客ID === currentUser.顧客ID) || customers[0];

      container.querySelector('#customer-name').textContent = customer.顧客名 || '';
      container.querySelector('#customer-code').textContent = customer.顧客コード || '';
      container.querySelector('#customer-contact').textContent = customer.担当者名 || '';
    }
  }

  // 商品テーブル再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const categories = tables.find(t => t.tableName === '商品カテゴリマスタ')?.records || [];
    const specs = tables.find(t => t.tableName === '商品仕様マスタ')?.records || [];
    const stocks = tables.find(t => t.tableName === '在庫マスタ')?.records || [];
    const customerPrices = tables.find(t => t.tableName === '顧客別単価マスタ')?.records || [];

    tbody.innerHTML = products.map(product => {
      const category = categories.find(c => c.カテゴリID === product.カテゴリID);
      const productSpecs = specs.filter(s => s.商品ID === product.商品ID && s.Web表示フラグ);
      const stock = stocks.find(s => s.商品ID === product.商品ID) || {};
      const customerPrice = customerPrices.find(cp => cp.商品ID === product.商品ID);

      const price = customerPrice ? customerPrice.単価 : product.単価;
      const stockCount = stock.発注可能数量 || 0;
      const specText = productSpecs.map(s => `${s.仕様名}:${s.仕様値}`).join(', ') || '-';

      const selected = selectedProducts.get(product.商品ID);
      const quantity = selected ? selected.quantity : 0;
      const subtotal = quantity * price;

      return `
        <tr data-id="${product.商品ID}">
          <td style="text-align: center;">
            <input type="checkbox" ${quantity > 0 ? 'checked' : ''} 
                   onchange="toggleProductSelection('${product.商品ID}')" 
                   style="accent-color: var(--primary);">
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${specText}</td>
          <td style="text-align: right;">${stockCount.toLocaleString()}</td>
          <td style="text-align: right;">¥${price.toLocaleString()}</td>
          <td>
            <input type="number" min="0" max="${stockCount}" value="${quantity}" 
                   onchange="updateQuantity('${product.商品ID}', this.value, ${price})"
                   style="width: 80px; padding: 4px 6px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 14px; text-align: right;">
          </td>
          <td style="text-align: right; font-weight: bold;">¥${subtotal.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 商品選択切り替え
  window.toggleProductSelection = function(productId) {
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const product = products.find(p => p.商品ID === productId);
    if (!product) return;

    if (selectedProducts.has(productId)) {
      selectedProducts.delete(productId);
    } else {
      selectedProducts.set(productId, { product, quantity: 1, subtotal: 0 });
    }

    // 商品一覧を再描画
    const currentProducts = Array.from(container.querySelectorAll('#product-tbody tr')).map(tr => {
      return products.find(p => p.商品ID === tr.dataset.id);
    }).filter(Boolean);
    renderProducts(currentProducts);
  };

  // 数量更新
  window.updateQuantity = function(productId, quantity, price) {
    const qty = parseInt(quantity) || 0;
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const product = products.find(p => p.商品ID === productId);

    if (qty > 0 && product) {
      selectedProducts.set(productId, { 
        product, 
        quantity: qty, 
        subtotal: qty * price 
      });
    } else {
      selectedProducts.delete(productId);
    }

    updateTotalAmount();
  };

  // 合計金額更新
  function updateTotalAmount() {
    let total = 0;
    selectedProducts.forEach(item => {
      total += item.subtotal;
    });
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const products = await window.aivicApi.list(1); // 商品マスタ
      if (products) {
        renderProducts(products.filter(p => p.公開フラグ && p.販売状態 === '販売中'));
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // 検索処理
  container.querySelector('#btn-search').addEventListener('click', async () => {
    try {
      const categoryId = container.querySelector('#category-select').value;
      const keyword = container.querySelector('#product-search').value.trim();

      const products = await window.aivicApi.list(1);
      if (!products) return;

      let filtered = products.filter(p => p.公開フラグ && p.販売状態 === '販売中');

      if (categoryId) {
        filtered = filtered.filter(p => p.カテゴリID === categoryId);
      }

      if (keyword) {
        filtered = filtered.filter(p => 
          (p.商品名 && p.商品名.includes(keyword)) || 
          (p.商品コード && p.商品コード.includes(keyword))
        );
      }

      renderProducts(filtered);
    } catch (error) {
      console.error('検索に失敗しました:', error);
    }
  });

  // クリア処理
  container.querySelector('#btn-clear').addEventListener('click', () => {
    if (confirm('選択した商品をすべてクリアしますか？')) {
      selectedProducts.clear();
      loadInitialData();
    }
  });

  // 発注処理
  container.querySelector('#btn-order').addEventListener('click', async () => {
    if (selectedProducts.size === 0) {
      alert('発注する商品を選択してください。');
      return;
    }

    const deliveryDate = container.querySelector('#delivery-date').value;
    const deliveryAddress = container.querySelector('#delivery-address').value;
    const notes = container.querySelector('#order-notes').value;

    if (!deliveryDate) {
      alert('希望納期を入力してください。');
      return;
    }

    try {
      const loginUsers = tables.find(t => t.tableName === 'ログインユーザー')?.records || [];
      const currentUser = loginUsers[0];

      if (!currentUser) {
        alert('ユーザー情報が取得できません。');
        return;
      }

      // 発注履歴を作成
      const orderNumber = 'ORD' + Date.now();
      let totalAmount = 0;

      for (const [productId, item] of selectedProducts) {
        const orderData = {
          発注番号: orderNumber,
          顧客ID: currentUser.顧客ID,
          商品ID: productId,
          発注数量: item.quantity,
          単価: item.subtotal / item.quantity,
          小計金額: item.subtotal,
          発注ステータス: '受注',
          発注日時: new Date().toISOString(),
          希望納期: deliveryDate + 'T00:00:00.000Z',
          備考: notes,
          作成者: currentUser.ユーザー名,
          更新者: currentUser.ユーザー名
        };

        const saved = await window.aivicApi.save(5, orderData); // 発注履歴
        if (!saved) {
          alert('発注の保存に失敗しました。');
          return;
        }

        totalAmount += item.subtotal;
      }

      alert(`発注が完了しました。\n発注番号: ${orderNumber}\n合計金額: ¥${totalAmount.toLocaleString()}`);

      // 発注履歴画面に遷移
      window.showScreen('scr-1780291083221');

    } catch (error) {
      console.error('発注処理に失敗しました:', error);
      alert('発注処理中にエラーが発生しました。');
    }
  });

  // 初期化
  setCustomerInfo();
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  let pageSize = 50;
  let filteredData = [];
  let allOrderHistory = [];

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    const statusStyles = {
      '未確定': 'background: rgba(255, 193, 7, 0.2); color: #ffc107; border: 1px solid #ffc107;',
      '確定': 'background: rgba(0, 123, 255, 0.2); color: #007bff; border: 1px solid #007bff;',
      '出荷済': 'background: rgba(40, 167, 69, 0.2); color: #28a745; border: 1px solid #28a745;',
      '完了': 'background: rgba(108, 117, 125, 0.2); color: #6c757d; border: 1px solid #6c757d;',
      'キャンセル': 'background: rgba(220, 53, 69, 0.2); color: #dc3545; border: 1px solid #dc3545;'
    };
    return `<span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500; ${statusStyles[status] || statusStyles['未確定']}">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#order-history-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 20px;">該当する発注履歴がありません</td></tr>';
      return;
    }

    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => `
      <tr data-id="${row.id || row.発注ID}" style="cursor: pointer;">
        <td style="color: var(--primary); font-weight: 500;">${row.発注番号 || row.orderNumber || ''}</td>
        <td>${row.発注日時 ? new Date(row.発注日時).toLocaleDateString('ja-JP') : (row.orderDate || '')}</td>
        <td>${row.商品名 || row.productName || ''}</td>
        <td style="text-align: right;">${(row.発注数量 || row.quantity || 0).toLocaleString()}</td>
        <td style="text-align: right;">¥${(row.単価 || row.unitPrice || 0).toLocaleString()}</td>
        <td style="text-align: right; font-weight: 600;">¥${(row.小計金額 || row.totalAmount || 0).toLocaleString()}</td>
        <td>${getStatusBadge(row.発注ステータス || row.status || '未確定')}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.id || row.発注ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; margin-right: 4px;">
            詳細
          </button>
          <button class="action-btn reorder-btn" data-id="${row.id || row.発注ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px;">
            再発注
          </button>
        </td>
      </tr>
    `).join('');

    updatePagination(rows.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / pageSize);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#prev-page');
    const nextBtn = container.querySelector('#next-page');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // 検索フィルター実行
  function applyFilters() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const orderNumber = container.querySelector('#order-number').value.toLowerCase();
    const productName = container.querySelector('#product-name').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const status = container.querySelector('#status-filter').value;

    filteredData = allOrderHistory.filter(row => {
      // 日付フィルター
      if (startDate || endDate) {
        const orderDate = new Date(row.発注日時 || row.orderDate);
        if (startDate && orderDate < new Date(startDate)) return false;
        if (endDate && orderDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // 発注番号フィルター
      if (orderNumber && !(row.発注番号 || row.orderNumber || '').toLowerCase().includes(orderNumber)) return false;

      // 商品名フィルター
      if (productName && !(row.商品名 || row.productName || '').toLowerCase().includes(productName)) return false;

      // カテゴリフィルター（実際の実装では商品マスタと結合が必要）
      if (category && row.カテゴリ !== category) return false;

      // ステータスフィルター
      if (status && (row.発注ステータス || row.status) !== status) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['発注番号', '発注日', '商品名', '数量', '単価', '金額', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredData.map(row => [
        `"${row.発注番号 || row.orderNumber || ''}"`,
        `"${row.発注日時 ? new Date(row.発注日時).toLocaleDateString('ja-JP') : (row.orderDate || '')}"`,
        `"${row.商品名 || row.productName || ''}"`,
        row.発注数量 || row.quantity || 0,
        row.単価 || row.unitPrice || 0,
        row.小計金額 || row.totalAmount || 0,
        `"${row.発注ステータス || row.status || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 発注詳細表示
  function showOrderDetail(orderId) {
    const order = allOrderHistory.find(o => (o.id || o.発注ID) === orderId);
    if (!order) return;

    const modal = container.querySelector('#order-detail-modal');
    const content = container.querySelector('#order-detail-content');

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px;">
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">発注番号</label>
          <div style="font-weight: 600; color: var(--text);">${order.発注番号 || order.orderNumber || ''}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">発注日時</label>
          <div style="color: var(--text);">${order.発注日時 ? new Date(order.発注日時).toLocaleString('ja-JP') : (order.orderDate || '')}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">商品名</label>
          <div style="color: var(--text);">${order.商品名 || order.productName || ''}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">数量</label>
          <div style="color: var(--text);">${(order.発注数量 || order.quantity || 0).toLocaleString()}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">単価</label>
          <div style="color: var(--text);">¥${(order.単価 || order.unitPrice || 0).toLocaleString()}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">合計金額</label>
          <div style="font-weight: 600; color: var(--text);">¥${(order.小計金額 || order.totalAmount || 0).toLocaleString()}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">ステータス</label>
          <div>${getStatusBadge(order.発注ステータス || order.status || '未確定')}</div>
        </div>
        <div>
          <label style="font-size: 12px; color: var(--text-muted);">希望納期</label>
          <div style="color: var(--text);">${order.希望納期 ? new Date(order.希望納期).toLocaleDateString('ja-JP') : (order.deliveryDate || '指定なし')}</div>
        </div>
      </div>
      ${order.備考 || order.notes ? `
        <div style="margin-top: 16px;">
          <label style="font-size: 12px; color: var(--text-muted);">備考</label>
          <div style="color: var(--text); margin-top: 4px; padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">${order.備考 || order.notes}</div>
        </div>
      ` : ''}
    `;

    modal.style.display = 'block';
  }

  // 初期データ読み込み
  window.aivicApi.list(5).then(rows => {
    if (rows) {
      allOrderHistory = rows;
      filteredData = [...rows];
      renderRows(filteredData);
    } else {
      // APIが利用できない場合は初期データを使用
      allOrderHistory = tables[5]?.records || [];
      filteredData = [...allOrderHistory];
      renderRows(filteredData);
    }
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#order-number').value = '';
    container.querySelector('#product-name').value = '';
    container.querySelector('#category-filter').value = '';
    container.querySelector('#status-filter').value = '';
    filteredData = [...allOrderHistory];
    currentPage = 1;
    renderRows(filteredData);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#page-size').addEventListener('change', (e) => {
    pageSize = parseInt(e.target.value);
    currentPage = 1;
    renderRows(filteredData);
  });

  container.querySelector('#prev-page').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector('#next-page').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredData.length / pageSize);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#order-detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-reorder').addEventListener('click', () => {
    window.showScreen('scr-1780291074387'); // 発注入力・確認画面
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const reorderBtn = e.target.closest('.reorder-btn');
    const row = e.target.closest('tr[data-id]');

    if (detailBtn) {
      e.stopPropagation();
      showOrderDetail(detailBtn.dataset.id);
    } else if (reorderBtn) {
      e.stopPropagation();
      window.showScreen('scr-1780291074387'); // 発注入力・確認画面
    } else if (row && row.dataset.id) {
      showOrderDetail(row.dataset.id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#order-detail-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });
}
